const crypto = require('crypto');
const sign = (payload) => 'sha256=' + crypto.createHmac('sha256', $env.WEBHOOK_SECRET).update(payload).digest('hex');
// Every page of the Gmail listing is one item: flatten and de-duplicate
const ids = [];
for (const page of $input.all()) for (const m of (page.json.messages || [])) ids.push(m.id);
const payload = JSON.stringify({ gmail_ids: [...new Set(ids)] });
return [{ json: { payload, signature: sign(payload) } }];

// Only messages the backend does not have yet are read from Gmail (saves quota)
const unknown = $input.first().json.unknown || [];
return unknown.length ? unknown.map(id => ({ json: { id, count: unknown.length } })) : [{ json: { count: 0 } }];

const crypto = require('crypto');
const sign = (payload) => 'sha256=' + crypto.createHmac('sha256', $env.WEBHOOK_SECRET).update(payload).digest('hex');
const runId = $('Start sync run').first().json.run_id;
const header = (h, n) => (h.find(x => x.name.toLowerCase() === n) || {}).value || '';
const decode = d => Buffer.from(d.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
function findPart(p, mime) {
  if (!p) return null;
  if (p.mimeType === mime && p.body && p.body.data) return p.body.data;
  for (const c of p.parts || []) { const r = findPart(c, mime); if (r) return r; }
  return null;
}
const addr = s => { const m = (s || '').match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>/); return m ? { name: m[1].trim(), email: m[2].trim() } : { name: '', email: (s || '').trim() }; };
const list = s => s ? s.split(',').map(x => addr(x).email).filter(Boolean) : [];
const htmlToText = html => html.replace(/<(style|script)[\s\S]*?<\/\1>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n\n')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\n\s+\n/g, '\n\n').trim();

// Messages Gmail refused to return (quota...) arrive as { error }: skipped here, re-read next run
const ok = $input.all().filter(({ json }) => json && json.id && json.payload);
const failed = $input.all().length - ok.length;
const emails = ok.map(({ json: m }) => {
  const h = (m.payload && m.payload.headers) || [];
  const plain = findPart(m.payload, 'text/plain');
  const html = findPart(m.payload, 'text/html');
  const body = plain ? decode(plain) : html ? htmlToText(decode(html)) : (m.snippet || '');
  const from = addr(header(h, 'from'));
  return {
    gmail_message_id: m.id,
    gmail_thread_id: m.threadId,
    from_name: from.name,
    from_email: from.email,
    to: list(header(h, 'to')),
    cc: list(header(h, 'cc')),
    subject: header(h, 'subject'),
    body_text: body.slice(0, 50000),
    received_at: new Date(Number(m.internalDate)).toISOString(),
    rfc_message_id: header(h, 'message-id') || null,
    references: header(h, 'references') || null,
  };
});

const out = [];
// Always at least one (possibly empty) batch, so the run is always closed
for (let i = 0; i < Math.max(emails.length, 1); i += 25) {
  const payload = JSON.stringify({ run_id: runId, emails: emails.slice(i, i + 25) });
  out.push({ json: { payload, signature: sign(payload), failed } });
}
return out;

const crypto = require('crypto');
const sign = (payload) => 'sha256=' + crypto.createHmac('sha256', $env.WEBHOOK_SECRET).update(payload).digest('hex');
const runId = $('Start sync run').first().json.run_id;
const fetched = $('Backend : messages déjà importés ?').first().json.total || 0;
let failed = 0;
try { failed = $('Extraire les champs + lots de 25').first().json.failed || 0; } catch (e) { /* nothing new this run */ }
// The cursor only moves when every message was read
const payload = JSON.stringify(failed
  ? { status: 'failed', fetched_count: fetched, error: failed + ' message(s) non lus (quota Gmail), repris au prochain passage' }
  : { status: 'success', fetched_count: fetched });
return [{ json: { payload, signature: sign(payload), run_id: runId } }];
